import{_ as a,o as t,c as n,ak as o}from"./chunks/framework.WYeQYp8i.js";const h=JSON.parse('{"title":"Code of Conduct","description":"","frontmatter":{"outline":2},"headers":[],"relativePath":"contributing/code-of-conduct.md","filePath":"contributing/code-of-conduct.md","lastUpdated":1794652862000}'),r={name:"contributing/code-of-conduct.md"};function i(s,e,c,l,p,d){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="code-of-conduct" tabindex="-1">Code of Conduct <a class="header-anchor" href="#code-of-conduct" aria-label="Permalink to &quot;Code of Conduct&quot;">​</a></h1><h2 id="our-pledge" tabindex="-1">Our pledge <a class="header-anchor" href="#our-pledge" aria-label="Permalink to &quot;Our pledge&quot;">​</a></h2><p>We as members, contributors, and maintainers pledge to make participation in our community a harassment-free experience for everyone, regardless of age, body size, visible or invisible disability, ethnicity, sex characteristics, gender identity and expression, level of experience, education, socio-economic status, nationality, personal appearance, race, religion, or sexual identity and orientation.</p><p>We pledge to act and interact in ways that contribute to an open, welcoming, diverse, inclusive, and healthy community.</p><h2 id="our-standards" tabindex="-1">Our standards <a class="header-anchor" href="#our-standards" aria-label="Permalink to &quot;Our standards&quot;">​</a></h2><p>Help make the community welcoming by:</p><ul><li>Treating others with empathy and kindness.</li><li>Respecting different opinions, experiences and levels of knowledge.</li><li>Giving constructive feedback and receiving it thoughtfully.</li><li>Discussing ideas and code without attacking the people behind them.</li><li>Taking responsibility for mistakes, apologising where appropriate and learning from them.</li><li>Respecting other people&#39;s time and boundaries. Contributions and support are provided voluntarily, and responses may take time.</li></ul><p>Unacceptable behaviour includes:</p><ul><li>Harassment, intimidation, threats or discriminatory abuse.</li><li>Trolling, insults, derogatory comments and personal attacks.</li><li>Sexualised language or imagery, and unwelcome sexual attention or advances.</li><li>Publishing or sharing someone&#39;s private information without their explicit permission.</li><li>Retaliation against anyone who reports a concern or participates in an investigation.</li><li>Other behaviour that reasonably makes participation unsafe or unwelcoming.</li></ul><p>Disagreement and constructive criticism are welcome. They should remain respectful and focused on the subject being discussed.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>This Code of Conduct applies to all project community spaces, including issues, pull requests, Discussions and other project communication channels. It also covers project-related harassment through private messages or external channels.</p><p>It applies when someone officially represents the project in public, such as through an official account or as an appointed representative at an event.</p><h2 id="reporting-a-concern" tabindex="-1">Reporting a concern <a class="header-anchor" href="#reporting-a-concern" aria-label="Permalink to &quot;Reporting a concern&quot;">​</a></h2><p>Report concerns privately to the project maintainers at <a href="mailto:conduct@greenimp.co.uk" target="_blank" rel="noreferrer">conduct@greenimp.co.uk</a>. Please do not open a public issue to report an incident.</p><p>You can report behaviour you experienced or witnessed. Include any relevant links, context or screenshots you feel comfortable sharing, where available. You do not need to provide a complete account or evidence before raising a concern.</p><p>Reports will be reviewed fairly, and maintainers will respond as soon as reasonably possible. The project is maintained voluntarily, so response times may vary.</p><p>Reports will be handled discreetly. Information will be shared only where necessary to investigate the concern or take appropriate action, with care for the privacy and safety of those involved.</p><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to &quot;Enforcement&quot;">​</a></h2><p>Maintainers are responsible for applying this Code of Conduct fairly. They may remove, edit or reject contributions, restrict interactions, or temporarily or permanently exclude someone from project spaces.</p><p>Decisions will take account of the severity and impact of the behaviour, its context and any previous incidents. The responses below are guidelines, not mandatory steps: serious incidents may result in an immediate temporary or permanent ban.</p><p>Maintainers will explain moderation decisions to those affected where appropriate, while respecting the privacy of others involved.</p><h3 id="correction" tabindex="-1">Correction <a class="header-anchor" href="#correction" aria-label="Permalink to &quot;Correction&quot;">​</a></h3><p>For an inappropriate comment or other less serious incident, maintainers may explain the concern privately and ask for the behaviour to stop or the content to be corrected.</p><h3 id="warning" tabindex="-1">Warning <a class="header-anchor" href="#warning" aria-label="Permalink to &quot;Warning&quot;">​</a></h3><p>For more serious or repeated behaviour, maintainers may issue a warning explaining what must change and the consequences of further violations. This may include a requirement to stop contacting particular people.</p><h3 id="temporary-ban" tabindex="-1">Temporary ban <a class="header-anchor" href="#temporary-ban" aria-label="Permalink to &quot;Temporary ban&quot;">​</a></h3><p>Serious or sustained misconduct may result in a temporary ban from project spaces. Maintainers will communicate its duration and any conditions, including restrictions on contacting those involved.</p><h3 id="permanent-ban" tabindex="-1">Permanent ban <a class="header-anchor" href="#permanent-ban" aria-label="Permalink to &quot;Permanent ban&quot;">​</a></h3><p>Severe misconduct, repeated violations or attempts to evade restrictions may result in permanent exclusion from the project community.</p><p>Retaliation, continued harassment or breaches of these restrictions may lead to further action.</p><h2 id="attribution" tabindex="-1">Attribution <a class="header-anchor" href="#attribution" aria-label="Permalink to &quot;Attribution&quot;">​</a></h2><p>This Code of Conduct is adapted from the <a href="https://www.contributor-covenant.org/version/2/0/code_of_conduct.html" target="_blank" rel="noreferrer">Contributor Covenant, version 2.0</a>, with project-specific reporting and enforcement guidance.</p><p>The original Community Impact Guidelines were inspired by <a href="https://github.com/mozilla/diversity" target="_blank" rel="noreferrer">Mozilla&#39;s code of conduct enforcement ladder</a>.</p><p>For more information about the Contributor Covenant, see its <a href="https://www.contributor-covenant.org/faq" target="_blank" rel="noreferrer">FAQ</a>.</p>',35)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
